"""Payment reminders: each reminder goes out at 09:00 in the tenant's time zone on its remind_on date.

schedule_reminder() is called when an invoice is finalized and stores the UTC send time.
"""
from datetime import date, datetime, time, timedelta, timezone
from zoneinfo import ZoneInfo

SEND_AT = time(9, 0)


def send_time_utc(remind_on: date, tz: str, now: datetime | None = None) -> datetime:
    """UTC instant for 09:00 local on remind_on, using the offset in force on that date (not today's)."""
    return datetime.combine(remind_on, SEND_AT, tzinfo=ZoneInfo(tz)).astimezone(timezone.utc)


def schedule_reminder(invoice_id: str, due: date, tz: str, now: datetime, days_before: int = 3) -> dict:
    remind_on = due - timedelta(days=days_before)
    return {"invoice_id": invoice_id, "remind_on": remind_on.isoformat(),
            "send_at_utc": send_time_utc(remind_on, tz, now).isoformat()}
